contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 loanID, address to) public payable {
        require(to != address(0), "zero to");

        // Create a loan; the test contract (msg.sender on calls to c) becomes its lender.
        uint256 amount = 1;
        uint256 interest = 0;
        uint256 loanToCollateral = 1;
        uint256 duration = 1;
        c.requestLoan(amount, interest, loanToCollateral, duration); if (__ESBMC_reverted()) return;

        bool cleared;
        uint256 createdID = c.clearRequest(0, false, false); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            cleared = false;
        } else {
            cleared = (createdID == 0);
        }
        require(cleared, "clearRequest did not create loan 0");

        // approveTransfer may only be called by the loan's lender, which is this test contract.
        bool ok;
        c.approveTransfer(to, 0); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            ok = false;
        } else {
            ok = true;
        }

        // approvals is mapping(uint256 => address); compare on the address type.
        assert(ok && c.approvals(0) == to);
    }

    receive() external payable {}
}

